<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\CompanyOnboarding;use App\Support\Url;Auth::requirePermission('COMPANY_VIEW_OWN');$company=CompanyOnboarding::current((int)Auth::user()['id']);if(!$company){header('Location: '.Url::to('company/onboarding.php'));exit;}$pageTitle='Company profile';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1><?=h($company['display_name'])?></h1><p>Company profile and verification state.</p></div><span class="badge"><?=h(ucfirst($company['verification_status']))?> verification</span></div><?php if(isset($_GET['created'])):?><div class="success">Company profile created successfully and submitted in a pending verification state.</div><?php endif;?><div class="grid"><div class="card"><h3>Identity</h3><dl class="definition"><dt>Reference</dt><dd><?=h($company['company_ref'])?></dd><dt>Legal name</dt><dd><?=h($company['legal_name'])?></dd><dt>Display name</dt><dd><?=h($company['display_name'])?></dd><dt>Type</dt><dd><?=h($company['type_name']??'Customer / Shipper')?></dd></dl></div><div class="card"><h3>Registration</h3><dl class="definition"><dt>Number</dt><dd><?=h($company['registration_number']?:'Not supplied')?></dd><dt>Country</dt><dd><?=h($company['registration_country']?:'Not supplied')?></dd><dt>Verification</dt><dd><?=h($company['verification_status'])?></dd><dt>Account status</dt><dd><?=h($company['status'])?></dd></dl></div><div class="card"><h3>Phase boundary</h3><p class="muted">Load creation, shipment tracking, documents, and payments are intentionally not implemented in this phase.</p></div></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
